mapper.select:
SELECT * FROM ( SELECT p.id,p.name,p.category,p.brand,p.summary,p.image_key,p.rating,p.sales_count, s.id AS sku_id,s.spec,s.price,s.original_price, 0 + CASE WHEN EXISTS(SELECT 1 FROM product_attribute a WHERE a.product_id=p.id AND a.attr_key='type' AND LOWER(a.attr_value) LIKE #{term} ESCAPE '!') THEN 15 WHEN LOWER(p.name) LIKE #{term} ESCAPE '!' THEN 8 WHEN LOWER(p.brand) LIKE #{term} ESCAPE '!' THEN 5 ELSE 1 END AS score, SUM(s.stock) OVER(PARTITION BY p.id) AS stock, COUNT(*) OVER(PARTITION BY p.id) AS sku_count, ROW_NUMBER() OVER(PARTITION BY p.id ORDER BY s.price,s.id) AS rn
) candidates WHERE rn=1 ORDER BY
price ASC,id ASC price DESC,id ASC sales_count DESC,id ASC rating DESC,sales_count DESC,id ASC score DESC,rating DESC,sales_count DESC,id ASC
LIMIT #{take} OFFSET #{skip}
